import {
  ArrowLeft,
  BookOpenText,
  ChevronRight,
  Clock3,
} from "lucide-react";
import type { CSSProperties } from "react";
import { useNavigate } from "react-router-dom";
import { READING_CHAPTERS } from "../../data/readingChapters";
import SpotlightCard from "../reactbits/vendor/SpotlightCard/SpotlightCard";
import "./reading.css";

export function ChapterLibrary() {
  const navigate = useNavigate();

  return (
    <main className="chapter-library">
      <header className="chapter-library__topbar" data-motion="enter">
        <button
          type="button"
          className="chapter-library__back"
          onClick={() => navigate("/")}
          aria-label="返回书房"
        >
          <ArrowLeft size={18} />
        </button>
        <span>
          <strong>章节阅读</strong>
          <small>Public-domain reading room</small>
        </span>
      </header>

      <section className="chapter-library__intro" data-motion="enter">
        <span className="chapter-library__eyebrow">Read directly</span>
        <h1>Four Classic Chapters</h1>
        <p>四本公版名著的完整原文选章。</p>
      </section>

      <section
        className="chapter-library__grid"
        aria-label="章节列表"
        data-motion="stagger"
      >
        {READING_CHAPTERS.map((chapter, index) => (
          <SpotlightCard
            key={chapter.id}
            as="button"
            className="chapter-card"
            style={
              {
                "--reading-accent": chapter.accent,
                "--reading-secondary": chapter.secondary,
              } as CSSProperties
            }
            onClick={() => navigate(`/reading/${chapter.id}`)}
            spotlightColor="rgba(47, 135, 171, 0.13)"
          >
            <span className="chapter-card__number">
              {String(index + 1).padStart(2, "0")}
            </span>
            <span className="chapter-card__icon">
              <BookOpenText size={22} />
            </span>
            <span className="chapter-card__meta">
              {chapter.author} · {chapter.chapter}
            </span>
            <strong>{chapter.title}</strong>
            <em>{chapter.zhTitle}</em>
            <p>{chapter.summaryZh}</p>
            <footer>
              <span>
                <Clock3 size={14} />
                {Math.max(1, Math.ceil(chapter.wordCount / 220))} min
              </span>
              <span>
                Read
                <ChevronRight size={15} />
              </span>
            </footer>
          </SpotlightCard>
        ))}
      </section>
    </main>
  );
}
